13	func TestSetPermissionHTTPSuccessAndIdempotency(t *testing.T) {
14		h, _ := newTestHandler(t)
15		registerDevice(t, h, "dev-1")
16		const url = "/v1/documents/doc1/permissions"
17	
18		// Devices start authorized: the first grant is a no-op.
19		w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "grant"})
20		if w.Code != http.StatusOK {
21			t.Fatalf("grant = %d body = %s", w.Code, w.Body.String())
22		}
23		if body["deviceId"] != "dev-1" || body["authorized"] != true || body["changed"] != false {
24			t.Fatalf("grant body = %v", body)
25		}
26	
27		// First revoke flips the state.
28		w, body = postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "revoke"})
29		if w.Code != http.StatusOK || body["authorized"] != false || body["changed"] != true {
30			t.Fatalf("revoke = %d %v body=%s", w.Code, body, w.Body.String())
31		}
32	
33		// Repeating the revoke is idempotent.
34		w, body = postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "revoke"})
35		if w.Code != http.StatusOK || body["authorized"] != false || body["changed"] != false {
36			t.Fatalf("revoke retry = %d %v", w.Code, body)
37		}
38	
39		// Re-grant flips back; repeating it is idempotent again.
40		w, body = postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "grant"})
41		if w.Code != http.StatusOK || body["authorized"] != true || body["changed"] != true {
42			t.Fatalf("re-grant = %d %v", w.Code, body)
43		}
44		w, body = postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "grant"})
45		if w.Code != http.StatusOK || body["changed"] != false {
46			t.Fatalf("grant retry = %d %v", w.Code, body)
47		}
48	}
