50	func TestSetPermissionHTTPRejectsBadInput(t *testing.T) {
51		h, s := newTestHandler(t)
52		registerDevice(t, h, "dev-1")
53		const url = "/v1/documents/doc1/permissions"
54	
55		cases := []struct {
56			name        string
57			contentType string
58			body        string
59		}{
60			{"wrong content type", "text/plain", `{"deviceId":"dev-1","action":"revoke"}`},
61			{"missing content type", "", `{"deviceId":"dev-1","action":"revoke"}`},
62			{"json suffix content type", "application/vnd.api+json", `{"deviceId":"dev-1","action":"revoke"}`},
63			{"malformed json", "application/json", `{`},
64			{"trailing content", "application/json", `{"deviceId":"dev-1","action":"revoke"}x`},
65			{"empty deviceId", "application/json", `{"deviceId":"","action":"revoke"}`},
66			{"missing deviceId", "application/json", `{"action":"revoke"}`},
67			{"numeric deviceId", "application/json", `{"deviceId":7,"action":"revoke"}`},
68			{"null deviceId", "application/json", `{"deviceId":null,"action":"revoke"}`},
69			{"missing action", "application/json", `{"deviceId":"dev-1"}`},
70			{"empty action", "application/json", `{"deviceId":"dev-1","action":""}`},
71			{"unknown action", "application/json", `{"deviceId":"dev-1","action":"block"}`},
72			{"numeric action", "application/json", `{"deviceId":"dev-1","action":1}`},
73			{"null action", "application/json", `{"deviceId":"dev-1","action":null}`},
74			{"array body", "application/json", `[1,2]`},
75			{"string body", "application/json", `"revoke"`},
76		}
77		for _, tc := range cases {
78			t.Run(tc.name, func(t *testing.T) {
79				r := newJSONRequest(http.MethodPost, url, tc.body, tc.contentType)
80				w := serveRecorder(h, r)
81				if w.Code != http.StatusBadRequest {
82					t.Fatalf("status = %d, want 400, body = %s", w.Code, w.Body.String())
83				}
84				assertJSONError(t, w)
85			})
86		}
87	
88		// Zero writes: the device is still on the default authorized state, so a
89		// real revoke now must report changed=true.
90		if ok, err := s.DocumentAuthorized("doc1", "dev-1"); err != nil || !ok {
91			t.Fatalf("zero-write violated: authorized=%v err=%v", ok, err)
92		}
93		w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev-1", "action": "revoke"})
94		if w.Code != http.StatusOK || body["changed"] != true {
95			t.Fatalf("revoke after rejects = %d %v", w.Code, body)
96		}
97	}
