129	func TestSessionChangesHTTPRevokedDevice403(t *testing.T) {
130		h, _ := newTestHandler(t)
131		registerDevice(t, h, "dev-1")
132		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
133		if w.Code != http.StatusOK {
134			t.Fatal(w.Body.String())
135		}
136		for i := 0; i < 2; i++ {
137			w, _ := postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
138				"deviceId": "dev-1",
139				"changes":  []any{map[string]any{"id": fmt.Sprintf("c%d", i), "payload": map[string]any{"i": i}}},
140			})
141			if w.Code != http.StatusOK {
142				t.Fatal(w.Body.String())
143			}
144		}
145	
146		// Authorized by default: the session view works.
147		w, body := doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
148		if w.Code != http.StatusOK || len(body["changes"].([]any)) != 2 {
149			t.Fatalf("before revoke = %d %v", w.Code, body)
150		}
151	
152		// Revoke the session's device for this document.
153		w, _ = postJSON(t, h, "/v1/documents/doc1/permissions", map[string]any{
154			"deviceId": "dev-1",
155			"action":   "revoke",
156		})
157		if w.Code != http.StatusOK {
158			t.Fatal(w.Body.String())
159		}
160	
161		// The session view is now a 403 JSON error carrying neither changes nor
162		// nextCursor.
163		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
164		if w.Code != http.StatusForbidden {
165			t.Fatalf("revoked read = %d, want 403, body = %s", w.Code, w.Body.String())
166		}
167		assertJSONError(t, w)
168		if _, ok := body["changes"]; ok {
169			t.Fatalf("403 must not return changes: %v", body)
170		}
171		if _, ok := body["nextCursor"]; ok {
172			t.Fatalf("403 must not return nextCursor: %v", body)
173		}
174	
175		// Revocation deletes nothing: the document view, merge and restore surface
176		// are untouched.
177		w, body = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes")
178		if w.Code != http.StatusOK || len(body["changes"].([]any)) != 2 {
179			t.Fatalf("document view after revoke = %d %v", w.Code, body)
180		}
181		w, _ = postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
182			"deviceId": "dev-1",
183			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"i": 2}}},
184		})
185		if w.Code != http.StatusOK {
186			t.Fatalf("post after revoke = %d %s", w.Code, w.Body.String())
187		}
188	
189		// Validation order is unchanged: bad params still 400, unknown session
190		// still 404, even while the permission is revoked.
191		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes?limit=0")
192		if w.Code != http.StatusBadRequest || body["error"] == nil {
193			t.Fatalf("bad params while revoked = %d %v", w.Code, body)
194		}
195		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/ghost/documents/doc1/changes")
196		if w.Code != http.StatusNotFound || body["error"] == nil {
197			t.Fatalf("unknown session while revoked = %d %v", w.Code, body)
198		}
199	
200		// The revocation is per document: another document reads fine.
201		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/other/changes")
202		if w.Code != http.StatusOK {
203			t.Fatalf("other document while revoked = %d %v", w.Code, body)
204		}
205	
206		// Re-grant restores the original session view.
207		w, _ = postJSON(t, h, "/v1/documents/doc1/permissions", map[string]any{
208			"deviceId": "dev-1",
209			"action":   "grant",
210		})
211		if w.Code != http.StatusOK {
212			t.Fatal(w.Body.String())
213		}
214		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
215		if w.Code != http.StatusOK || len(body["changes"].([]any)) != 3 || body["nextCursor"].(float64) != 3 {
216			t.Fatalf("after re-grant = %d %v", w.Code, body)
217		}
218	}
