220	func TestPermissionHTTPRestartPersists(t *testing.T) {
221		path := filepath.Join(t.TempDir(), "sync.db")
222	
223		s, err := app.Open(path)
224		if err != nil {
225			t.Fatal(err)
226		}
227		h := NewHandler(s)
228		registerDevice(t, h, "dev-1")
229		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
230		if w.Code != http.StatusOK {
231			t.Fatal(w.Body.String())
232		}
233		w, body := postJSON(t, h, "/v1/documents/doc1/permissions", map[string]any{
234			"deviceId": "dev-1",
235			"action":   "revoke",
236		})
237		if w.Code != http.StatusOK || body["changed"] != true {
238			t.Fatalf("revoke = %d %v", w.Code, body)
239		}
240		if err := s.Close(); err != nil {
241			t.Fatal(err)
242		}
243	
244		s2, err := app.Open(path)
245		if err != nil {
246			t.Fatal(err)
247		}
248		t.Cleanup(func() { _ = s2.Close() })
249		h2 := NewHandler(s2)
250	
251		// The revoked state and its idempotency survive the restart.
252		w, _ = doRequest(t, h2, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
253		if w.Code != http.StatusForbidden {
254			t.Fatalf("read after restart = %d, want 403", w.Code)
255		}
256		w, body = postJSON(t, h2, "/v1/documents/doc1/permissions", map[string]any{
257			"deviceId": "dev-1",
258			"action":   "revoke",
259		})
260		if w.Code != http.StatusOK || body["changed"] != false {
261			t.Fatalf("revoke replay after restart = %d %v", w.Code, body)
262		}
263		w, body = postJSON(t, h2, "/v1/documents/doc1/permissions", map[string]any{
264			"deviceId": "dev-1",
265			"action":   "grant",
266		})
267		if w.Code != http.StatusOK || body["changed"] != true {
268			t.Fatalf("grant after restart = %d %v", w.Code, body)
269		}
270		w, _ = doRequest(t, h2, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
271		if w.Code != http.StatusOK {
272			t.Fatalf("read after re-grant = %d, want 200", w.Code)
273		}
274	}
