276	func TestConcurrentGrantRevokeHTTP(t *testing.T) {
277		h, _ := newTestHandler(t)
278		registerDevice(t, h, "dev")
279		const url = "/v1/documents/doc/permissions"
280	
281		// Concurrent identical revokes: exactly one reports changed=true.
282		const n = 40
283		var wg sync.WaitGroup
284		var mu sync.Mutex
285		changed := 0
286		errs := make(chan error, n)
287		for i := 0; i < n; i++ {
288			wg.Add(1)
289			go func() {
290				defer wg.Done()
291				w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
292				if w.Code != http.StatusOK {
293					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
294					return
295				}
296				if body["changed"] == true {
297					mu.Lock()
298					changed++
299					mu.Unlock()
300				}
301			}()
302		}
303		wg.Wait()
304		close(errs)
305		for err := range errs {
306			t.Fatal(err)
307		}
308		if changed != 1 {
309			t.Fatalf("changed reporters = %d, want 1", changed)
310		}
311	
312		// Concurrent grant vs. revoke settles into one coherent state: a repeat of
313		// the observed state is a no-op.
314		var wg2 sync.WaitGroup
315		statuses := make(chan int, 2)
316		wg2.Add(2)
317		for _, action := range []string{"grant", "revoke"} {
318			go func(action string) {
319				defer wg2.Done()
320				w, _ := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": action})
321				statuses <- w.Code
322			}(action)
323		}
324		wg2.Wait()
325		close(statuses)
326		for code := range statuses {
327			if code != http.StatusOK {
328				t.Fatalf("racing grant/revoke status = %d", code)
329			}
330		}
331		// Settle: force a known state, then confirm a repeat is a no-op.
332		w, _ := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
333		if w.Code != http.StatusOK {
334			t.Fatal(w.Body.String())
335		}
336		w, body := postJSON(t, h, url, map[string]any{"deviceId": "dev", "action": "revoke"})
337		if w.Code != http.StatusOK || body["changed"] != false {
338			t.Fatalf("settled revoke repeat = %d %v", w.Code, body)
339		}
340	}
341	
342	// Ensure a racing read observes either the full pre- or post-revoke state,
343	// never an error or a partial response.
344	func TestConcurrentRevokeAndSessionReadHTTP(t *testing.T) {
345		h, _ := newTestHandler(t)
346		registerDevice(t, h, "dev")
347		w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "sess"})
348		if w.Code != http.StatusOK {
349			t.Fatal(w.Body.String())
350		}
351		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
352			"deviceId": "dev",
353			"changes":  []any{map[string]any{"id": "c", "payload": map[string]any{"k": 1}}},
354		})
355		if w.Code != http.StatusOK {
356			t.Fatal(w.Body.String())
357		}
358	
359		var wg sync.WaitGroup
360		errs := make(chan error, 2)
361		wg.Add(2)
362		go func() {
363			defer wg.Done()
364			w, _ := postJSON(t, h, "/v1/documents/doc/permissions", map[string]any{
365				"deviceId": "dev",
366				"action":   "revoke",
367			})
368			if w.Code != http.StatusOK {
369				errs <- fmt.Errorf("revoke status %d", w.Code)
370			}
371		}()
372		go func() {
373			defer wg.Done()
374			w, body := doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc/changes")
375			switch w.Code {
376			case http.StatusOK:
377				if len(body["changes"].([]any)) != 1 {
378					errs <- fmt.Errorf("200 without the change: %v", body)
379				}
380			case http.StatusForbidden:
381				if _, ok := body["changes"]; ok {
382					errs <- fmt.Errorf("403 with changes: %v", body)
383				}
384			default:
385				errs <- fmt.Errorf("read status %d", w.Code)
386			}
387		}()
388		wg.Wait()
389		close(errs)
390		for err := range errs {
391			t.Fatal(err)
392		}
393	}
