		"deviceId": "dev-1",
		"action":   "revoke",
	})
	if w.Code != http.StatusOK || body["changed"] != false {
		t.Fatalf("revoke replay after restart = %d %v", w.Code, body)
	}
	w, body = postJSON(t, h2, "/v1/documents/doc1/permissions", map[string]any{
		"deviceId": "dev-1",
