		w, body := doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc/changes")
		switch w.Code {
		case http.StatusOK:
			if len(body["changes"].([]any)) != 1 {
				errs <- fmt.Errorf("200 without the change: %v", body)
			}
		case http.StatusForbidden:
