122		// Concurrent identical revokes: exactly one reports a change.
123		const n = 40
124		var wg sync.WaitGroup
125		var mu sync.Mutex
126		changedCount := 0
127		errCh := make(chan error, n+2)
128		for i := 0; i < n; i++ {
129			wg.Add(1)
130			go func() {
131				defer wg.Done()
132				changed, err := s.SetDocumentPermission("doc", "dev", false)
133				if err != nil {
134					errCh <- err
135					return
136				}
137				if changed {
138					mu.Lock()
139					changedCount++
140					mu.Unlock()
141				}
142			}()
143		}
144		wg.Wait()
145		if changedCount != 1 {
146			t.Fatalf("changed reporters = %d, want 1", changedCount)
147		}
148		if ok, _ := s.DocumentAuthorized("doc", "dev"); ok {
149			t.Fatal("device should be revoked after concurrent revokes")
150		}
151	
152		// Concurrent grant vs. revoke: each commits completely, so the settled
153		// state is coherent — a repeat of the observed state is a no-op.
154		var wg2 sync.WaitGroup
155		wg2.Add(2)
156		go func() {
157			defer wg2.Done()
158			if _, err := s.SetDocumentPermission("doc", "dev", true); err != nil {
159				errCh <- err
160			}
161		}()
162		go func() {
163			defer wg2.Done()
164			if _, err := s.SetDocumentPermission("doc", "dev", false); err != nil {
165				errCh <- err
166			}
167		}()
168		wg2.Wait()
169		close(errCh)
170		for err := range errCh {
171			t.Fatal(err)
172		}
173		final, err := s.DocumentAuthorized("doc", "dev")
174		if err != nil {
175			t.Fatal(err)
176		}
177		changed, err := s.SetDocumentPermission("doc", "dev", final)
178		if err != nil || changed {
179			t.Fatalf("repeat of settled state = changed:%v err:%v, want no-op", changed, err)
180		}
