317	func TestContentCharsetAccepted(t *testing.T) {
318		h, _ := newTestHandler(t)
319		// application/json with charset parameter is still application/json.
320		r := httptest.NewRequest(http.MethodPost, "/v1/documents/doc/changes",
321			strings.NewReader(`{"deviceId":"d","changes":[{"id":"a","payload":1}]}`))
