201			assertJSONError(t, w)
202		}
203	
204		// A non-creator gets a 403 for an existing attachment — even dev-2,
205		// which is currently granted read access — and the body leaks no device
206		// ids.
207		for _, caller := range []string{"dev-2", "dev-3"} {
208			w, _ := getAccessRoster(t, h, rosterURL(caller, "att-1", ""))
209			if w.Code != http.StatusForbidden {
210				t.Fatalf("roster as %s = %d, want 403", caller, w.Code)
211			}
212			assertJSONError(t, w)
213			if strings.Contains(w.Body.String(), "dev-") {
214				t.Fatalf("403 body leaks roster: %s", w.Body.String())
215			}
216		}
217	
218		// The 403s changed no state: dev-2 still reads and still appears.
219		if w := getAttachmentMeta(t, h, "dev-2", "att-1"); w.Code != http.StatusOK {
220			t.Fatalf("granted read after 403 roster = %d, want 200", w.Code)
221		}
222		_, devices := getAccessRoster(t, h, rosterURL("dev-1", "att-1", ""))
223		if !equalStrings(devices, []string{"dev-2"}) {
224			t.Fatalf("roster after 403s = %v, want [dev-2]", devices)
225		}
226	
227		// Deleting the attachment turns the roster into a stable 404 for
228		// everyone, leaving no roster content behind.
229		deleteAttachment(t, h, "dev-1", "att-1")
230		for _, caller := range []string{"dev-1", "dev-2"} {
231			w, _ := getAccessRoster(t, h, rosterURL(caller, "att-1", ""))
232			if w.Code != http.StatusNotFound {
233				t.Fatalf("roster after delete as %s = %d, want 404", caller, w.Code)
234			}
235			assertJSONError(t, w)
236			if strings.Contains(w.Body.String(), "dev-") {
237				t.Fatalf("post-delete 404 body leaks roster: %s", w.Body.String())
238			}
239		}
240	
241		// Re-creating the same id starts a brand-new roster: the old grants were
242		// deleted with the attachment and never come back.
243		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("data"), 2)
244		w, devices := getAccessRoster(t, h, rosterURL("dev-1", "att-1", ""))
245		if w.Code != http.StatusOK || len(devices) != 0 {
246			t.Fatalf("roster after recreate = %d %v, want empty 200", w.Code, devices)
247		}
248		// The old grant does not read either.
249		if w := getAttachmentMeta(t, h, "dev-2", "att-1"); w.Code != http.StatusForbidden {
250			t.Fatalf("old grantee read after recreate = %d, want 403", w.Code)
251		}
252	}
253	
254	// Empty identifiers, missing or extra segments and verbs other than GET are
255	// all 400 JSON errors — never a redirect or HTML — and change nothing.
256	func TestAttachmentAccessRosterShapeContract(t *testing.T) {
257		h, _ := newTestHandler(t)
258		registerDevice(t, h, "dev-1")
259		registerDevice(t, h, "dev-2")
260		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("data"), 2)
261		setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
262	
263		cases := []struct {
264			method string
265			path   string
266		}{
267			// Empty identifiers and trailing slashes.
268			{http.MethodGet, "/v1/devices//attachments/att-1/access"},
269			{http.MethodGet, "/v1/devices/dev-1/attachments//access"},
270			{http.MethodGet, "/v1/devices/dev-1/attachments/att-1/access/"},
271			// Missing or extra segments.
272			{http.MethodGet, "/v1/devices/dev-1/attachments/att-1/access/extra"},
273			{http.MethodPost, "/v1/devices/dev-1/attachments/att-1/access/extra"},
274			{http.MethodDelete, "/v1/devices/dev-1/attachments/att-1/access/extra"},
275			// Verbs other than GET/POST on the access subresource.
276			{http.MethodPut, "/v1/devices/dev-1/attachments/att-1/access"},
277			{http.MethodDelete, "/v1/devices/dev-1/attachments/att-1/access"},
278			{http.MethodPatch, "/v1/devices/dev-1/attachments/att-1/access"},
279			{http.MethodOptions, "/v1/devices/dev-1/attachments/att-1/access"},
280		}
281		for _, tc := range cases {
282			r := httptest.NewRequest(tc.method, tc.path, nil)
283			w := serveRecorder(h, r)
284			if w.Code != http.StatusBadRequest {
285				t.Fatalf("%s %s = %d, want 400", tc.method, tc.path, w.Code)
286			}
287			assertJSONError(t, w)
288			if ct := w.Header().Get("Content-Type"); ct != "application/json" {
289				t.Fatalf("%s %s content-type = %q, want application/json", tc.method, tc.path, ct)
290			}
291		}
292	
293		// Zero writes: the grant is intact and POST still drives access changes.
294		_, devices := getAccessRoster(t, h, rosterURL("dev-1", "att-1", ""))
295		if !equalStrings(devices, []string{"dev-2"}) {
296			t.Fatalf("roster after rejected shapes = %v", devices)
297		}
298		w, body := setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
299		if w.Code != http.StatusOK || body["changed"] != true {
300			t.Fatalf("POST access after shape rejects = %d %v", w.Code, body)
301		}
302	}
303	
304	// The roster is a read-only view: content and order are byte-for-byte
305	// identical across a process restart.
306	func TestAttachmentAccessRosterSurvivesRestart(t *testing.T) {
307		dbPath := filepath.Join(t.TempDir(), "sync.db")
308		open := func(t *testing.T) (http.Handler, *app.App) {
309			t.Helper()
310			s, err := app.Open(dbPath)
311			if err != nil {
312				t.Fatal(err)
313			}
314			return NewHandler(s), s
315		}
316	
317		h, s := open(t)
318		registerDevice(t, h, "dev-1")
319		registerDevice(t, h, "dev-2")
320		registerDevice(t, h, "dev-3")
321		mustCreateAttachment(t, h, "dev-1", "att-1", []byte("data"), 2)
322		setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
323		setAccess(t, h, "dev-1", "att-1", "dev-3", "grant")
324		setAccess(t, h, "dev-1", "att-1", "dev-2", "revoke")
325		setAccess(t, h, "dev-1", "att-1", "dev-2", "grant")
326	
327		snapshot := func(t *testing.T, h http.Handler) map[string]string {
328			t.Helper()
329			bodies := map[string]string{}
330			for _, query := range []string{"", "limit=1&offset=0", "limit=1&offset=1", "offset=2"} {
331				r := httptest.NewRequest(http.MethodGet, rosterURL("dev-1", "att-1", query), nil)
332				w := serveRecorder(h, r)
333				if w.Code != http.StatusOK {
334					t.Fatalf("GET ?%q = %d", query, w.Code)
335				}
336				bodies[query] = w.Body.String()
337			}
338			return bodies
339		}
340	
341		before := snapshot(t, h)
342		_ = s.Close()
343	
344		h, s = open(t)
345		defer func() { _ = s.Close() }()
346		after := snapshot(t, h)
347		for query, body := range before {
348			if after[query] != body {
349				t.Fatalf("GET ?%q after restart = %s, want %s", query, after[query], body)
350			}
351		}
352	}
