272	
273		r := httptest.NewRequest(http.MethodDelete, "/v1/devices/dev-1/attachments/att-1", nil)
274		if w := serveRecorder(h, r); w.Code != http.StatusOK {
275			t.Fatalf("delete = %d", w.Code)
276		}
277		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusNotFound {
278			t.Fatalf("content after delete = %d, want 404", w.Code)
279		} else {
280			assertJSONError(t, w)
281		}
282	
283		// The id is free again: a fresh upload under it is unsealed, so the
284		// whole-content read is a 409 until the new upload finishes.
285		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
286		if w := getAttachmentContent(t, h, "dev-1", "att-1"); w.Code != http.StatusConflict {
287			t.Fatalf("recreated unsealed read = %d, want 409", w.Code)
288		}
