291	// The whole-content read and its judgments are durable: after a restart the
292	// sealed bytes read back identically and the 403/404/409 decisions are
293	// unchanged.
294	func TestAttachmentContentSurvivesRestart(t *testing.T) {
295		dbPath := filepath.Join(t.TempDir(), "sync.db")
296		open := func(t *testing.T) (http.Handler, *app.App) {
297			t.Helper()
298			s, err := app.Open(dbPath)
299			if err != nil {
300				t.Fatal(err)
301			}
302			return NewHandler(s), s
303		}
304	
305		h, s := open(t)
306		registerDevice(t, h, "dev-1")
307		registerDevice(t, h, "dev-2")
308		content := []byte("hello world")
309		mustCreateAttachment(t, h, "dev-1", "att-1", content, 4)
310		putChunk(t, h, "dev-1", "att-1", 0, []byte("hell"))
311		putChunk(t, h, "dev-1", "att-1", 1, []byte("o wo"))
312		putChunk(t, h, "dev-1", "att-1", 2, []byte("rld"))
313		w, body := completeAttachment(t, h, "dev-1", "att-1")
314		if w.Code != http.StatusOK || body["complete"] != true {
315			t.Fatalf("complete = %d %v", w.Code, body)
316		}
317		w, _ = postJSON(t, h, "/v1/devices/dev-1/attachments/att-1/access", map[string]any{
318			"deviceId": "dev-2", "action": "grant",
319		})
320		if w.Code != http.StatusOK {
321			t.Fatalf("grant = %d %s", w.Code, w.Body.String())
322		}
