332			if w.Code != http.StatusOK || w.Body.String() != string(content) ||
333				w.Header().Get("Content-Type") != "application/octet-stream" {
334				t.Fatalf("content after restart (%s) = %d %q %q",
335					device, w.Code, w.Body.String(), w.Header().Get("Content-Type"))
336			}
337		}
338		if w := getAttachmentContent(t, h, "dev-1", "att-2"); w.Code != http.StatusConflict {
339			t.Fatalf("unsealed after restart = %d, want 409", w.Code)
