346	// The content read is read-only: it changes neither the metadata view nor the
347	// chunk-level reads, and it coexists with the per-chunk contract — the
348	// assembled body is exactly the per-chunk bytes in ascending index order.
349	func TestAttachmentContentMatchesPerChunkReads(t *testing.T) {
