13	// seedSnapshots stores snapshots at the given cursors with verbatim raw
14	// states, after first seeding enough changes for the cursors to exist.
15	func seedSnapshots(t *testing.T, h http.Handler, doc string, states map[int]string) {
16		t.Helper()
17		max := 0
18		for c := range states {
19			if c > max {
20				max = c
21			}
22		}
23		seedDoc(t, h, doc, max)
24		for cursor, state := range states {
25			w, _ := postJSON(t, h, "/v1/documents/"+doc+"/snapshots",
26				`{"cursor":`+strconv.Itoa(cursor)+`,"state":`+state+`}`)
27			if w.Code != http.StatusOK {
28				t.Fatalf("seed snapshot %d status = %d body = %s", cursor, w.Code, w.Body.String())
29			}
30		}
31	}
32	
33	func TestExportSnapshotsHTTPSuccess(t *testing.T) {
34		h, _ := newTestHandler(t)
35		seedSnapshots(t, h, "doc1", map[int]string{
36			1: "null",
37			2: `42`,
38			3: `"str"`,
39			4: `[1,2]`,
40			5: `{"a":1}`,
41		})
42	
43		// No parameters: from defaults to 0, no upper bound. The body is one
44		// compact line with keys ordered snapshots,count and item keys ordered
45		// cursor,state; exactly one trailing newline.
46		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
47		if w.Code != http.StatusOK {
48			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
49		}
50		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
51			t.Fatalf("content type = %q", ct)
52		}
53		want := `{"snapshots":[` +
54			`{"cursor":1,"state":null},` +
55			`{"cursor":2,"state":42},` +
56			`{"cursor":3,"state":"str"},` +
57			`{"cursor":4,"state":[1,2]},` +
58			`{"cursor":5,"state":{"a":1}}` +
59			`],"count":5}` + "\n"
60		if w.Body.String() != want {
61			t.Fatalf("body = %q\nwant %q", w.Body.String(), want)
62		}
63	
64		// Closed interval includes both endpoints.
65		w, _ = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=2&to=4")
66		if w.Code != http.StatusOK {
67			t.Fatalf("range status = %d", w.Code)
68		}
69		want = `{"snapshots":[` +
70			`{"cursor":2,"state":42},` +
71			`{"cursor":3,"state":"str"},` +
72			`{"cursor":4,"state":[1,2]}` +
73			`],"count":3}` + "\n"
74		if w.Body.String() != want {
75			t.Fatalf("range body = %q\nwant %q", w.Body.String(), want)
76		}
77	
78		// Degenerate interval matches the single cursor.
79		w, _ = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=3&to=3")
80		if got := strings.TrimSpace(w.Body.String()); got != `{"snapshots":[{"cursor":3,"state":"str"}],"count":1}` {
81			t.Fatalf("point body = %q", got)
82		}
83	
84		// Lower bound only (to absent).
85		w, _ = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=5")
86		if got := strings.TrimSpace(w.Body.String()); got != `{"snapshots":[{"cursor":5,"state":{"a":1}}],"count":1}` {
87			t.Fatalf("from-only body = %q", got)
88		}
89	
90		// Explicit empty parameters behave like defaults.
91		w, _ = doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots?from=&to=")
92		if w.Code != http.StatusOK || strings.Count(w.Body.String(), `"cursor"`) != 5 {
93			t.Fatalf("empty params = %d %s", w.Code, w.Body.String())
94		}
95	}
96	
97	func TestExportSnapshotsHTTPEmpty(t *testing.T) {
98		h, _ := newTestHandler(t)
99		seedSnapshots(t, h, "doc1", map[int]string{2: `{"v":1}`, 4: `{"v":2}`})
100	
101		// An interval with no snapshot (gap, but within the document) is a
102		// successful empty list.
103		for _, url := range []string{
104			"/v1/documents/doc1/snapshots?from=3&to=3",
105			"/v1/documents/doc1/snapshots?from=5",
106			"/v1/documents/doc1/snapshots?from=99&to=200",
107		} {
108			w, _ := doRequest(t, h, http.MethodGet, url)
109			if w.Code != http.StatusOK {
110				t.Fatalf("%s status = %d", url, w.Code)
111			}
112			if got := w.Body.String(); got != `{"snapshots":[],"count":0}`+"\n" {
113				t.Fatalf("%s body = %q", url, got)
114			}
115		}
116	
117		// An unknown document is also a successful empty list, not a 404.
118		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/nope/snapshots")
119		if w.Code != http.StatusOK {
120			t.Fatalf("unknown doc status = %d", w.Code)
121		}
122		if got := w.Body.String(); got != `{"snapshots":[],"count":0}`+"\n" {
123			t.Fatalf("unknown doc body = %q", got)
124		}
125	}
126	
127	func TestExportSnapshotsHTTPStateMatchesSingleRead(t *testing.T) {
128		h, _ := newTestHandler(t)
129		states := map[int]string{1: `{"z":1,"a":2}`, 3: `[true,null,{"n":0.5}]`}
130		seedSnapshots(t, h, "doc1", states)
131	
132		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/snapshots")
