40	// dialWS performs the opening handshake against an httptest.Server URL. A
41	// non-101 response is returned as (nil, response) so tests can assert the
42	// 400/403/404 JSON failures.
43	func dialWS(t *testing.T, serverURL string) (*wsClient, *http.Response) {
44		t.Helper()
45		u, err := url.Parse(serverURL)
46		if err != nil {
47			t.Fatal(err)
48		}
49		conn, err := net.DialTimeout("tcp", u.Host, 2*time.Second)
50		if err != nil {
51			t.Fatalf("dial: %v", err)
52		}
