func guard(p string) bool {
	// mimic documentSegmentEmpty only
	return len(p) >= 15 && p[:15] == "/v1/documents//"
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(200) })
	mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(201) })
	mux.HandleFunc("/v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(400) })
	mux.HandleFunc("/v1/documents/{documentID}/permissions/{rest...}", func(w http.ResponseWriter, r *http.Request) {
		fmt.Println("  wildcard rest=", fmt.Sprintf("%q", r.PathValue("rest")))
		w.WriteHeader(400)
	})
