518	func TestConcurrentSessionLifecycleHTTP(t *testing.T) {
519		h, _ := newTestHandler(t)
520		registerDevice(t, h, "dev")
521	
522		// Concurrent identical creates: exactly one creator.
523		const n = 40
524		var wg sync.WaitGroup
525		var mu sync.Mutex
526		creators := 0
527		errs := make(chan error, n)
528		for i := 0; i < n; i++ {
529			wg.Add(1)
530			go func() {
531				defer wg.Done()
532				w, body := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
533				if w.Code != http.StatusOK {
534					errs <- fmt.Errorf("status %d: %s", w.Code, w.Body.String())
535					return
536				}
537				if body["created"] == true {
538					mu.Lock()
539					creators++
540					mu.Unlock()
541				}
542			}()
543		}
544		wg.Wait()
545		close(errs)
546		for err := range errs {
547			t.Fatal(err)
548		}
549		if creators != 1 {
550			t.Fatalf("creators = %d, want 1", creators)
551		}
552	
553		// Concurrent delete vs. create: in the end exactly one of {live, absent}
554		// holds consistently, and the next state is coherent (repeat delete 404s
555		// iff the delete won; create reports created=true iff it ran after removal).
556		var wg2 sync.WaitGroup
557		statuses := make(chan int, 2)
558		wg2.Add(2)
559		go func() {
560			defer wg2.Done()
561			w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
562			statuses <- w.Code
563		}()
564		go func() {
565			defer wg2.Done()
566			w, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "hot"})
567			statuses <- w.Code
568		}()
569		wg2.Wait()
570		close(statuses)
571		for code := range statuses {
572			if code != http.StatusOK {
573				t.Fatalf("racing delete/create status = %d", code)
574			}
575		}
576	
577		// The race settles into exactly one coherent state (live or absent). A
578		// final owner delete then forces "absent": 200 if it was live, 404 if the
579		// racing delete already won. Afterwards both the read and a repeat delete
580		// must observe the same absent state — no half-deleted or duplicated row.
581		w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
582		if w.Code != http.StatusOK && w.Code != http.StatusNotFound {
583			t.Fatalf("settling delete = %d", w.Code)
584		}
585		w, _ = doRequest(t, h, http.MethodGet, "/v1/sessions/hot/documents/d/changes")
586		if w.Code != http.StatusNotFound {
587			t.Fatalf("session should be absent after settle, GET = %d", w.Code)
588		}
589		w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/hot")
590		if w.Code != http.StatusNotFound {
591			t.Fatalf("repeat delete after settle = %d, want 404", w.Code)
592		}
593	}
